func TestLoad(t *testing.T) {
	tests := []struct {
		name     string
		path     string
		wantErr  error
		expected func() *Config
		warnings []string
	}{
		{
			name:     "defaults",
			path:     "./testdata/default.yml",
			expected: Default,
		},
		{
			name: "deprecated tracing jaeger enabled",
